import sys
import time
import hashlib

def compute_digest(file_path):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            hasher.update(chunk)
    return hasher.hexdigest()

def main(manifest_path):
    count = 0
    with open(manifest_path, 'w') as manifest_file:
        for line in sys.stdin:
            path = line.strip()
            if path:
                digest = compute_digest(path)
                manifest_file.write(f"{digest} {path}\n")
                count += 1
                time.sleep(0.2)  # Wait for 0.2 seconds before processing the next file
    print(count)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python digest_manifest.py <manifest-path>")
        sys.exit(1)
    manifest_path = sys.argv[1]
    main(manifest_path)

import sys
import hashlib
import time

def compute_digest(file_path, algorithm):
    with open(file_path, 'rb') as f:
        return hashlib.new(algorithm, f.read()).hexdigest()

def main():
    manifest_path = sys.stdin.readline().strip()
    algorithm = sys.stdin.readline().strip()
    files = [line.strip() for line in sys.stdin if line.strip()]

    with open(manifest_path, 'w') as manifest:
        for i, file_path in enumerate(files, 1):
            if i > 1:
                time.sleep(0.2)
            digest = compute_digest(file_path, algorithm)
            manifest.write(f"{digest} {file_path}\n")

    print(len(files))

if __name__ == "__main__":
    main()
